// Diamond Mine adapts BreatheQuest's indicator-level / completed-cycle game concept.
// Source: https://github.com/modamaan/spirometer (see SOURCE.md).
let game='balloon',mineScore=0,mineCount=0,mineState='ready',mineCooldown=0,minePaused=false,mineHistory=[];
const gameSection=document.querySelector('.game'),originalTitle=document.querySelector('.gamehead>span').innerHTML;
const chooser=document.createElement('nav');chooser.className='gamePicker';chooser.setAttribute('aria-label','Choose a game');chooser.innerHTML='<button id="balloonGame" aria-pressed="true">🎈 Balloon Adventure</button><button id="mineGame" aria-pressed="false">💎 Diamond Mine <small>NEW</small></button>';document.querySelector('.intro').after(chooser);
const mineScene=document.createElement('div');mineScene.id='mineScene';mineScene.hidden=true;mineScene.innerHTML='<div class="miner">🤖<div id="beam"></div></div><div id="loot">🪙 <span>💎</span> ✨</div><div class="mineCaption">Find a little treasure.<br><small>Move, release, and watch it sparkle.</small></div>';gameSection.append(mineScene);
const board=document.createElement('section');board.id='scoreboard';board.hidden=true;board.innerHTML='<div class="boardTitle"><div><span class="eyebrow">YOUR TREASURE CHEST</span><h2>Scoreboard</h2></div><span id="boardMode">Practice · simulated</span></div><div class="scoreStats"><div><strong id="mineScore">0</strong><span>POINTS THIS ROUND</span></div><div><strong id="mineCount">0 / 5</strong><span>TREASURES COLLECTED</span></div><div><strong id="mineBest">0</strong><span>BEST ON THIS DEVICE</span></div></div><p id="mineInstructions">Hold and release the practice button to collect a treasure. Each one earns 10 points.</p><div class="boardActions"><button id="pauseMine">Pause</button><button id="newRound">New round</button></div><h3>Recent rounds</h3><ol id="rounds"><li>Your first treasure hunt is waiting.</li></ol><p class="hint" id="storageNote">Only game scores are saved in this browser. Practice and camera scores stay separate.</p><button id="clearScores">Clear saved scores</button><p class="hint">Game points are not breathing measurements. Take breaks and follow your prescribed routine.</p><a class="sourceLink" href="https://github.com/modamaan/spirometer" target="_blank" rel="noopener">Inspired by BreatheQuest · view source ↗</a>';document.querySelector('.bottom').before(board);
try{const parsed=JSON.parse(localStorage.getItem('little-lungs-mine-v1')||'[]');if(Array.isArray(parsed))mineHistory=parsed.filter(r=>r&&['practice','camera'].includes(r.mode)&&Number.isInteger(r.score)&&r.score>=0&&r.score<=50).slice(0,10)}catch{}
function updateBoard(){const history=mineHistory.filter(r=>r.mode===mode);$('mineScore').textContent=mineScore;$('mineCount').textContent=`${mineCount} / 5`;$('mineBest').textContent=Math.max(0,...history.map(r=>r.score),mineScore);$('boardMode').textContent=mode==='practice'?'Practice · simulated':'Camera · experimental';$('rounds').replaceChildren(...(history.length?history.map((r,i)=>{const li=document.createElement('li');li.textContent=`Round ${history.length-i} · ${r.score} points · ${r.score/10} treasures`;return li}):[Object.assign(document.createElement('li'),{textContent:'Your first treasure hunt is waiting.'})]));$('mineInstructions').textContent=mode==='practice'?'Hold and release the practice button to collect a treasure. Each one earns 10 points.':'Use your prescribed routine. A tracked lift and return collects a treasure for 10 points. More force earns no extra points.';$('stars').textContent=game==='mine'?`💎 ${mineScore} pts`:$('stars').textContent}
function resetMine(){held=false;mineScore=0;mineCount=0;mineState='ready';mineCooldown=0;minePaused=false;$('pauseMine').textContent='Pause';$('newRound').disabled=false;updateBoard();if(game==='mine')say('Hello, treasure hunter! Go at your own pace.')}
function chooseGame(next){game=next;held=false;active=0;points=0;rest=0;lift=0;gameSection.classList.toggle('mining',game==='mine');gameSection.setAttribute('aria-label',game==='mine'?'Diamond Mine':'Balloon adventure');mineScene.hidden=game!=='mine';board.hidden=game!=='mine';$('balloonGame').setAttribute('aria-pressed',String(game==='balloon'));$('mineGame').setAttribute('aria-pressed',String(game==='mine'));document.querySelector('.gamehead>span').innerHTML=game==='mine'?'💎 &nbsp; Diamond Mine <small>A LITTLE TREASURE HUNT</small>':originalTitle;$('float').textContent=game==='mine'?'Hold, then release to collect 💎':'Hold to float ↑';document.querySelector('#practicePanel .center').innerHTML=game==='mine'?'Hold to pull a treasure closer.<br>Release to collect. Take your time.':'Press and hold to help Pip float.<br>Let go to take a little break.';document.querySelector('.intro p').innerHTML=game==='mine'?'A little movement. A sparkling discovery.<br>Collect treasures in your own time.':'Your spirometer is the controller.<br>Help Pip float through a sky full of surprises.';if(game==='mine')resetMine();else{$('stars').textContent='☆ 0 / 3';say('Hi, I’m Pip. Ready to explore?')}}
$('balloonGame').onclick=()=>chooseGame('balloon');$('mineGame').onclick=()=>chooseGame('mine');$('newRound').onclick=resetMine;$('pauseMine').onclick=()=>{minePaused=!minePaused;held=false;mineState='ready';$('pauseMine').textContent=minePaused?'Resume':'Pause';say(minePaused?'Paused. Take a comfortable break.':'Ready whenever you are.')};$('clearScores').onclick=()=>{mineHistory=[];try{localStorage.removeItem('little-lungs-mine-v1')}catch{}updateBoard()};
function mineFrame(input,dt,valid){if(minePaused||$('help').open||document.hidden)return;mineCooldown=Math.max(0,mineCooldown-dt);$('loot').style.transform=`translateX(${-Math.min(input,.5)*100}px)`;$('beam').style.opacity=input>.15?'1':'0';if(!valid){mineState='ready';return}if(mineState==='done')return;if(mineCooldown>0)return;if(mineState==='ready'&&input>.15){mineState='collecting';say('A treasure is on its way. Release when ready.')}else if(mineState==='collecting'&&input<.1){mineScore+=10;mineCount++;mineCooldown=2;mineState=mineCount>=5?'done':'ready';updateBoard();say(mineCount>=5?'50 points! Your treasure chest is full. Take a break.':`Sparkle! +10 points. ${mineCount} treasures collected.`);if(mineCount>=5){mineHistory.unshift({score:mineScore,mode});mineHistory=mineHistory.slice(0,10);try{localStorage.setItem('little-lungs-mine-v1',JSON.stringify(mineHistory))}catch{$('storageNote').textContent='Browser storage is unavailable. Scores last only while this page stays open.'}updateBoard()}}}
const switchInput=m=>{select(m);if(game==='mine'){updateBoard();say(m==='camera'?'Let’s set up the camera with a grown-up.':'Hello, treasure hunter! Go at your own pace.')}};
$('practice').onclick=()=>switchInput('practice');$('camera').onclick=()=>switchInput('camera');
updateBoard();
